insert into public.page_revisions (page_id, number, kind, content, message)
select id, 1, 'seed', $cms${"fields":{"a-propos.page.a-1":{"text":"Aller au contenu","href":"#main"},"a-propos.header.card_index-1":{"href":"index.html"},"a-propos.s1.span-1":{"text":"À propos"},"a-propos.s1.h1-1":{"text":"Ana est née d'une question simple : pourquoi ce travail n'est-il toujours pas automatisé ?"},"a-propos.s1.p-1":{"text":"Clara travaille depuis 7 ans dans la finance d'entreprise, entre cabinet d'expertise comptable et directions financières. Chaque clôture, chaque échéance, c'est le même scénario : des journées qui finissent tard, et une grande partie du temps absorbée par des tâches répétitives, collecter les pièces, ressaisir, rapprocher, vérifier."},"a-propos.s2.p-1":{"text":"Notre histoire"},"a-propos.s2.h2-1":{"text":"Vu de près, puis remis en question"},"a-propos.s2.p-2":{"text":"Son frère Romain voyait ça de près. Avec Marco, tous deux vendent de la technologie aux entreprises depuis 5 ans et savent ce que l'IA agentique permet aujourd'hui. Une question s'est imposée : pourquoi ce travail n'est-il toujours pas automatisé ?"},"a-propos.s2.p-3":{"text":"La réponse tenait en deux constats. Les outils d'IA existants ne sont pas pensés pour la réalité des process financiers français. Et aucune équipe finance ne confiera ses chiffres à une IA qu'elle ne peut ni contrôler ni vérifier."},"a-propos.s2.p-4":{"text":"Le parti pris"},"a-propos.s2.h2-2":{"text":"Répondre aux deux, à la fois"},"a-propos.s2.p-5":{"text":"Ana est née pour répondre aux deux constats : des agents construits avec le métier, sur une architecture pensée pour la traçabilité, et pensés pour toute la fonction finance, pas seulement la production comptable. Nous ne cherchons pas à remplacer un expert-comptable ni un DAF, nous voulons leur rendre les heures perdues sur des tâches sans arbitrage, et laisser la décision là où elle a de la valeur."},"a-propos.s3.h2-1":{"text":"Ce que nous faisons"},"a-propos.s3.p-1":{"text":"Ana déploie des agents IA qui prennent en charge le travail répétitif des fonctions financières, en PME comme en cabinet."},"a-propos.s3.li-1":{"text":"Collecte et extraction des pièces : factures, relevés, justificatifs."},"a-propos.s3.li-2":{"text":"Pré-rapprochements bancaires, soumis à validation."},"a-propos.s3.li-3":{"text":"Relances clients et suivi du recouvrement."},"a-propos.s3.li-4":{"text":"Contrôles de cohérence et détection d'anomalies."},"a-propos.s3.li-5":{"text":"Reporting de gestion et diagnostic financier express à partir du FEC."},"a-propos.s3.p-2":{"text":"Chaque agent suit la même règle : il prépare, un professionnel valide."},"a-propos.s4.h2-1":{"text":"Notre approche"},"a-propos.s4.p-1":{"text":"Calculer, puis narrer"},"a-propos.s4.p-2":{"text":"Les chiffres sont produits par un moteur de calcul déterministe. L'IA explique et rédige, elle n'invente jamais un montant."},"a-propos.s4.p-3":{"text":"Tout est traçable"},"a-propos.s4.p-4":{"text":"Chaque action d'un agent est journalisée et explicable. Pas de boîte noire."},"a-propos.s4.p-5":{"text":"L'humain garde la main"},"a-propos.s4.p-6":{"text":"Les étapes sensibles passent toujours par une validation humaine."},"a-propos.s4.p-7":{"text":"Souverain par conception"},"a-propos.s4.p-9":{"text":"Données pseudonymisées avant traitement, hébergement dans l'Union européenne, RGPD intégré dès la conception."},"a-propos.s5.h2-1":{"text":"L'équipe"},"a-propos.s5.p-1":{"text":"Ana réunit ce qui manque à la plupart des outils finance : une experte qui connaît les process de l'intérieur, et deux profils qui savent comment les entreprises achètent, déploient et adoptent la technologie."},"a-propos.s5.img-1":{"src":"assets/img/clara-innocenzi.jpg","alt":"Clara Innocenzi"},"a-propos.s5.p-2":{"text":"Clara Innocenzi"},"a-propos.s5.p-3":{"text":"Co-fondatrice"},"a-propos.s5.p-4":{"text":"Clara connaît les process financiers de l'intérieur : elle travaille depuis 7 ans en cabinet d'expertise comptable et en direction financière, et prépare actuellement le diplôme d'expertise comptable. Chez Ana, elle accompagne toute la partie métier, comptabilité, trésorerie, contrôle de gestion et s'assure que nos agents IA travaillent comme le ferait un professionnel."},"a-propos.s5.img-2":{"src":"assets/img/marco-stefanovic.jpg","alt":"Marco Stefanovic"},"a-propos.s5.p-5":{"text":"Marco Stefanovic"},"a-propos.s5.p-6":{"text":"Co-fondateur"},"a-propos.s5.p-7":{"text":"5 ans dans la vente de logiciels, sur une solution de calcul d'empreinte carbone. Marco apporte à Ana sa connaissance du terrain commercial : comment une entreprise évalue un logiciel, ce qui la convainc et ce qui freine l'adoption."},"a-propos.s5.img-3":{"src":"assets/img/romain-innocenzi.jpg","alt":"Romain Innocenzi"},"a-propos.s5.p-8":{"text":"Romain Innocenzi"},"a-propos.s5.p-9":{"text":"Co-fondateur"},"a-propos.s5.p-10":{"text":"5 ans dans la vente tech, passé par Capgemini où il accompagnait de grands comptes sur des projets technologiques et informatiques. Romain apporte à Ana la rigueur des projets en grande organisation : cadrage, sécurité, conformité, conduite du changement."},"a-propos.s6.h2-1":{"text":"Nos valeurs"},"a-propos.s6.p-1":{"text":"Le métier d'abord"},"a-propos.s6.p-2":{"text":"Chaque agent part d'un process réel, conçu avec quelqu'un qui le pratique depuis des années."},"a-propos.s6.p-3":{"text":"La transparence comme standard"},"a-propos.s6.p-4":{"text":"Un chiffre qu'on ne peut pas expliquer n'a rien à faire dans un livrable."},"a-propos.s6.p-5":{"text":"Utile avant d'être impressionnant"},"a-propos.s6.p-6":{"text":"On automatise ce qui fait gagner du temps, pas ce qui brille en démo."},"a-propos.s6.p-7":{"text":"Partenaires des métiers de la finance"},"a-propos.s6.p-8":{"text":"Ana intervient en appui des experts-comptables, des directions financières et des équipes de gestion, dans le respect du périmètre réservé à chaque profession."},"a-propos.s7.p-1":{"text":"Notre vision"},"a-propos.s7.h2-1":{"text":"Le répétitif aux agents, l'expertise aux humains"},"a-propos.s7.p-2":{"text":"Demain, chaque fonction finance travaillera avec une équipe d'agents IA qui prend en charge le répétitif. Les professionnels de la finance consacreront leur temps à ce qui exige vraiment leur expertise : analyser, conseiller, décider."},"a-propos.s7.p-3":{"text":"Notre ambition"},"a-propos.s7.h2-2":{"text":"Qu'aucune équipe finance ne finisse plus tard le soir"},"a-propos.s7.p-4":{"text":"Notre ambition est simple : qu'aucun comptable, contrôleur de gestion ou membre d'une direction financière ne finisse plus tard le soir sur une tâche qu'un agent aurait pu préparer."},"a-propos.s8.h2-1":{"text":"Envie de voir ce que les agents Ana peuvent faire pour votre fonction finance ?"},"a-propos.s8.p-2":{"text":"Une courte démo, sur vos propres flux : on cartographie les tâches automatisables et le gain attendu."},"a-propos.s8.a-1":{"text":"Demander une démo","href":"demo.html"},"a-propos.page.a-2":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5","s6","s7","s8"],"hidden":[]},"seo":{"title":"À propos — Ana Finance","description":"L'équipe et la mission d'Ana Finance : automatiser la finance sans jamais remplacer le jugement humain.","ogTitle":"À propos — Ana Finance","ogDescription":"L'équipe et la mission d'Ana Finance : automatiser la finance sans jamais remplacer le jugement humain.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
where slug = 'a-propos' and not exists (select 1 from public.page_revisions r where r.page_id = pages.id);
insert into public.page_drafts (page_id, content, version)
select r.page_id, r.content, 1 from public.page_revisions r join public.pages p on p.id = r.page_id
