select id, 1, 'seed', $cms${"fields":{"agents.page.a-1":{"text":"Aller au contenu","href":"#main"},"agents.header.card_index-1":{"href":"index.html"},"agents.header.span-3":{"text":"Une famille d'agents par domaine : rapprochement, relances, TVA, clôture, et Agent Control qui contrôle le travail des autres."},"agents.page.a-2":{"text":"Accueil","href":"index.html"},"agents.page.a-3":{"text":"Fonctionnalités","href":"comment-ca-marche.html"},"agents.page.span-1":{"text":"Les agents Ana"},"agents.s1.span-1":{"text":"Fonctionnalités"},"agents.s1.h1-1":{"text":"Une famille d'agents par métier de la production financière."},"agents.s1.p-1":{"text":"Ana n'est pas un agent unique à tout faire. Chaque famille a son périmètre, ses règles de gestion et son niveau d'autonomie, et Agent Control contrôle le travail des autres."},"agents.s2.span-1":{"text":"L'organisation"},"agents.s2.h2-1":{"text":"Six agents exécutent. Agent Control les contrôle tous."},"agents.s2.p-13":{"text":"Les agents se passent le travail de proche en proche, dans l'ordre. Au-dessus d'eux, un agent de contrôle rejoue leurs décisions à chaque traitement, c'est ce qui rend l'automatisation acceptable dans un métier où l'erreur se paie."},"agents.s2.span-2":{"text":"01"},"agents.s2.p-2":{"text":"Vos flux, branchés en place"},"agents.s2.p-3":{"text":"Banques DSP2"},"agents.s2.p-4":{"text":"Soldes et mouvements, en lecture seule"},"agents.s2.p-5":{"text":"Factures & justificatifs"},"agents.s2.p-6":{"text":"Achats, ventes, notes de frais"},"agents.s2.p-7":{"text":"Logiciel comptable, ERP"},"agents.s2.p-8":{"text":"Plan comptable, journaux, analytique"},"agents.s2.span-3":{"text":"02"},"agents.s2.p-14":{"text":"Six agents d'exécution, sous le contrôle d'Agent Control"},"agents.s2.span-4":{"text":"1"},"agents.s2.span-5":{"text":"Collecte"},"agents.s2.span-6":{"text":"Ingestion des pièces"},"agents.s2.span-7":{"text":"2"},"agents.s2.span-8":{"text":"Rapprochement"},"agents.s2.span-9":{"text":"Lettrage bancaire"},"agents.s2.span-10":{"text":"3"},"agents.s2.span-11":{"text":"Relances"},"agents.s2.span-12":{"text":"Encours clients"},"agents.s2.span-13":{"text":"4"},"agents.s2.span-14":{"text":"TVA"},"agents.s2.span-15":{"text":"Bases déclaratives"},"agents.s2.span-16":{"text":"5"},"agents.s2.span-17":{"text":"Clôture"},"agents.s2.span-18":{"text":"Checklist périodique"},"agents.s2.span-19":{"text":"6"},"agents.s2.span-20":{"text":"Reporting"},"agents.s2.span-21":{"text":"Tableaux de bord"},"agents.s2.span-22":{"text":"Agent Control"},"agents.s2.span-35":{"text":"Contrôle les six agents, à chaque traitement"},"agents.s2.span-24":{"text":"Rejoue un échantillon"},"agents.s2.span-25":{"text":"Détecte les dérives"},"agents.s2.span-26":{"text":"Tient le journal complet"},"agents.s2.span-27":{"text":"Rend tout réversible"},"agents.s2.span-28":{"text":"03"},"agents.s2.p-10":{"text":"Décision, puis restitution"},"agents.s2.p-11":{"text":"Validation humaine"},"agents.s2.span-29":{"html":"<strong style=\"color:#6d28d9;\">Niveau 1</strong>, observation, rien n'est écrit"},"agents.s2.span-30":{"html":"<strong style=\"color:#6d28d9;\">Niveau 2</strong>, accord humain avant écriture"},"agents.s2.span-31":{"html":"<strong style=\"color:#6d28d9;\">Niveau 3</strong>, autonome sous votre seuil"},"agents.s2.p-12":{"text":"Écritures & reporting"},"agents.s2.span-32":{"text":"Poussés dans vos outils existants"},"agents.s2.span-33":{"text":"Journal complet attaché à chaque écriture"},"agents.s2.span-34":{"text":"Annulable à tout moment, état antérieur conservé"},"agents.s3.h2-1":{"text":"Les six agents d'exécution"},"agents.s3.p-1":{"text":"Chacun a son périmètre, ses règles de gestion et son niveau d'autonomie propre. Cliquez une carte pour voir ce que l'agent fait exactement."},"agents.s3.span-1":{"text":"Ingestion"},"agents.s3.span-2":{"text":"Agent Collecte"},"agents.s3.span-3":{"text":"Récupère les pièces là où elles arrivent et les prépare pour le traitement."},"agents.s3.span-4":{"text":"Voir en grand"},"agents.s3.li-1":{"text":"Boîtes mail dédiées, dépôts client, portails fournisseurs, drive partagé."},"agents.s3.li-2":{"text":"Lecture des factures et reçus, extraction des montants, TVA, échéances et références."},"agents.s3.li-3":{"text":"Détection des doublons et des pièces manquantes avant traitement."},"agents.s3.li-4":{"text":"Relance automatique du client ou du fournisseur pour une pièce absente."},"agents.s3.li-5":{"html":"<strong>Passe la main à :</strong> Agent Rapprochement."},"agents.s3.span-5":{"text":"Trésorerie"},"agents.s3.span-6":{"text":"Agent Rapprochement"},"agents.s3.span-7":{"text":"Associe les mouvements bancaires aux pièces et propose l'écriture."},"agents.s3.span-8":{"text":"Voir en grand"},"agents.s3.li-6":{"text":"Lettrage facture / paiement, y compris paiements partiels et regroupés."},"agents.s3.li-7":{"text":"Gestion des écarts de change et des frais bancaires."},"agents.s3.li-8":{"text":"Proposition d'imputation selon votre plan comptable et vos habitudes."},"agents.s3.li-9":{"text":"Les cas ambigus partent en file de validation, jamais en écriture forcée."},"agents.s3.li-10":{"html":"<strong>Passe la main à :</strong> Agent Relances pour les impayés, Agent Clôture en fin de période."},"agents.s3.span-9":{"text":"Recouvrement"},"agents.s3.span-10":{"text":"Agent Relances"},"agents.s3.span-11":{"text":"Suit les encours clients et relance selon votre scénario."},"agents.s3.span-12":{"text":"Voir en grand"},"agents.s3.li-11":{"text":"Scénario de relance paramétrable : délais, ton, canaux, escalade."},"agents.s3.li-12":{"text":"Arrêt automatique dès réception du paiement, signalé par l'Agent Rapprochement."},"agents.s3.li-13":{"text":"Signalement des litiges et des promesses de paiement à traiter en humain."},"agents.s3.li-14":{"text":"Historique complet des échanges attaché au compte client."},"agents.s3.span-13":{"text":"Fiscal"},"agents.s3.span-14":{"text":"Agent TVA & déclaratif"},"agents.s3.span-15":{"text":"Prépare les bases déclaratives et signale les anomalies avant dépôt."},"agents.s3.span-16":{"text":"Voir en grand"},"agents.s3.li-15":{"text":"Contrôle de cohérence des taux et des régimes appliqués."},"agents.s3.li-16":{"text":"Rapprochement TVA collectée / déductible et détection des écarts."},"agents.s3.li-17":{"text":"Préparation des éléments de la déclaration, avec les pièces justificatives liées."},"agents.s3.li-18":{"text":"Le dépôt reste une action humaine : Ana prépare, vous validez."},"agents.s3.span-17":{"text":"Périodique"},"agents.s3.span-18":{"text":"Agent Clôture"},"agents.s3.span-19":{"text":"Déroule la checklist de clôture et prépare les écritures récurrentes."},"agents.s3.span-20":{"text":"Voir en grand"},"agents.s3.li-19":{"text":"Cut-off, abonnements, amortissements, provisions récurrentes."},"agents.s3.li-20":{"text":"Suivi d'avancement par dossier et par étape, avec les blocages remontés."},"agents.s3.li-21":{"text":"Comparaison à la période précédente pour repérer les variations inexpliquées."},"agents.s3.li-28":{"text":"Dossier de clôture constitué au fil des imports, prêt pour la révision."},"agents.s3.li-23":{"html":"<strong>Passe la main à :</strong> Agent Reporting."},"agents.s3.span-21":{"text":"Pilotage"},"agents.s3.span-22":{"text":"Agent Reporting"},"agents.s3.span-23":{"text":"Met à jour les tableaux de bord et les livrables récurrents."},"agents.s3.span-24":{"text":"Voir en grand"},"agents.s3.li-24":{"text":"Reporting mensuel, points de trésorerie, écarts budgétaires."},"agents.s3.li-25":{"text":"Commentaire automatique des variations les plus significatives."},"agents.s3.li-26":{"text":"Diffusion au bon destinataire selon le calendrier convenu."},"agents.s3.li-27":{"text":"Export vers vos formats existants, pas de nouveau format à adopter."},"agents.s4.span-1":{"text":"Agent de contrôle, au-dessus des six"},"agents.s4.h2-1":{"text":"Agent Control"},"agents.s4.p-1":{"text":"Il n'exécute aucune tâche de production. Son seul travail est de vérifier celui des autres : il rejoue un échantillon de leurs décisions, compare la règle appliquée à la règle attendue, et alerte avant que l'erreur ne se propage dans les comptes."},"agents.s4.li-1":{"html":"<strong>Échantillonnage.</strong> Rejoue les décisions de chaque agent et mesure le taux de concordance."},"agents.s4.li-2":{"html":"<strong>Détection de dérive.</strong> Taux inhabituel, imputation atypique, doublon, montant hors norme."},"agents.s4.li-3":{"html":"<strong>Journal complet.</strong> Qui a décidé quoi, quand, sur quelle pièce et selon quelle règle."},"agents.s4.li-4":{"html":"<strong>Réversibilité.</strong> L'état antérieur est conservé : toute action peut être annulée."},"agents.s4.p-5":{"text":"Ce que fait Agent Control, à chaque traitement"},"agents.s4.span-2":{"html":"<span style=\"width:6px;height:6px;border-radius:50%;background:#ffd6f5;flex:none;\"></span>Lettrage proposé"},"agents.s4.span-3":{"html":"<span style=\"width:6px;height:6px;border-radius:50%;background:#ffd6f5;flex:none;\"></span>Taux de TVA retenu"},"agents.s4.span-4":{"html":"<span style=\"width:6px;height:6px;border-radius:50%;background:#ffd6f5;flex:none;\"></span>Imputation choisie"},"agents.s4.p-3":{"text":"Rejoue la décision"},"agents.s4.p-4":{"html":"règle appliquée<br>vs règle attendue"},"agents.s4.span-5":{"text":"Verdict"},"agents.s4.span-6":{"text":"Concordant"},"agents.s4.span-7":{"text":"Décision conservée, journalisée, réversible"},"agents.s4.span-8":{"text":"Écart détecté"},"agents.s4.span-9":{"text":"Alerte immédiate, retour en validation humaine"},"agents.s5.h2-1":{"text":"Trois niveaux d'autonomie, à régler agent par agent"},"agents.s5.p-1":{"text":"Un même agent peut être en observation sur un dossier et autonome sur un autre. Le réglage se change à tout moment, sans interruption de service."},"agents.s5.p-2":{"text":"Niveau 1"},"agents.s5.p-3":{"text":"Observation"},"agents.s5.p-4":{"text":"L'agent propose, rien n'est écrit. Utile pour calibrer les règles sur un dossier."},"agents.s5.p-5":{"text":"Niveau 2"},"agents.s5.p-6":{"text":"Validation"},"agents.s5.p-7":{"text":"Chaque action passe en file d'attente et attend un accord humain avant écriture."},"agents.s5.p-8":{"text":"Niveau 3"},"agents.s5.p-9":{"text":"Autonome sous seuil"},"agents.s5.p-10":{"text":"L'agent exécute seul sous un seuil que vous fixez ; au-delà, retour en validation."},"agents.s6.span-1":{"text":"Le principe"},"agents.s6.p-1":{"text":"Un agent qui exécute sans qu'on puisse vérifier son raisonnement n'a pas sa place dans des comptes."},"agents.s6.p-2":{"text":"C'est pourquoi Agent Control existe avant tout le reste, et pourquoi chaque décision reste réversible."},"agents.s7.h2-1":{"text":"Voyons ce qu'Ana reprendrait chez vous."},"agents.s7.p-2":{"text":"Une courte démo, sur vos propres flux : on cartographie les tâches automatisables et le gain attendu."},"agents.s7.a-1":{"text":"Demander une démo","href":"demo.html"},"agents.page.a-4":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5","s6","s7"],"hidden":[]},"seo":{"title":"Les agents Ana — Ana Finance","description":"Découvrez les agents Ana (dont Agent Control) : chaque action est supervisée, journalisée et réversible.","ogTitle":"Les agents Ana — Ana Finance","ogDescription":"Découvrez les agents Ana (dont Agent Control) : chaque action est supervisée, journalisée et réversible.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
