insert into public.page_revisions (page_id, number, kind, content, message)
select id, 1, 'seed', $cms${"fields":{"cabinets.page.a-1":{"text":"Aller au contenu","href":"#main"},"cabinets.header.card_index-1":{"href":"index.html"},"cabinets.page.a-2":{"text":"Accueil","href":"index.html"},"cabinets.page.a-3":{"text":"Cas d'usage","href":"directions-financieres.html"},"cabinets.page.span-1":{"text":"Cabinets comptables"},"cabinets.s1.span-1":{"text":"Cas d'usage, Cabinets comptables"},"cabinets.s1.h1-1":{"text":"Absorbez la production, rendez du temps à la révision et au conseil."},"cabinets.s1.p-1":{"text":"Votre portefeuille grossit, le recrutement ne suit pas, et la production répétitive mange les journées de vos collaborateurs. Ana exécute cette production dossier par dossier."},"cabinets.s1.span-2":{"text":"Aucune migration de logiciel"},"cabinets.s1.span-3":{"text":"Journal complet"},"cabinets.s1.span-4":{"text":"Vos collaborateurs valident"},"cabinets.s2.span-1":{"text":"Ce qu'Ana exécute"},"cabinets.s2.h2-1":{"text":"La production que vos collaborateurs ne refont plus à la main."},"cabinets.s2.p-1":{"text":"Cliquez une bulle pour voir ce qu'Ana fait exactement."},"cabinets.s2.span-2":{"text":"Saisie & imputation des pièces"},"cabinets.s2.span-3":{"text":"Factures, notes de frais et relevés extraits, contrôlés et imputés selon le plan comptable de chaque dossier."},"cabinets.s2.span-4":{"text":"Voir le détail"},"cabinets.s2.span-5":{"text":"Récupération depuis les portails, e-mails et dépôts clients"},"cabinets.s2.span-6":{"text":"Contrôle TVA, mentions obligatoires, doublons et devise"},"cabinets.s2.span-7":{"text":"Imputation selon les habitudes de chaque dossier, pas une règle générique"},"cabinets.s2.span-38":{"text":"Rapprochement bancaire à chaque import"},"cabinets.s2.span-39":{"text":"Tous les dossiers pointés à chaque import. Seuls les écarts qui résistent remontent à votre collaborateur."},"cabinets.s2.span-10":{"text":"Voir le détail"},"cabinets.s2.span-11":{"text":"Paiements partiels, regroupés et frais bancaires gérés"},"cabinets.s2.span-12":{"text":"Lettrage automatique avec conservation de vos conventions"},"cabinets.s2.span-13":{"text":"File d'écarts par dossier, avec hypothèse de résolution"},"cabinets.s2.span-14":{"text":"Régularisations préparées"},"cabinets.s2.span-15":{"text":"FNP, CCA, provisions et abonnements récurrents proposés avec leur justification et leur pièce jointe."},"cabinets.s2.span-16":{"text":"Voir le détail"},"cabinets.s2.span-17":{"text":"Détection des charges et produits à cheval sur l'exercice"},"cabinets.s2.span-18":{"text":"Étalement automatique des contrats et abonnements"},"cabinets.s2.span-19":{"text":"Chaque écriture porte sa pièce et sa règle, prête à réviser"},"cabinets.s2.span-20":{"text":"Clôtures prêtes à réviser"},"cabinets.s2.span-21":{"text":"Le dossier arrive construit : on révise et on signe, au lieu de le monter dans l'urgence."},"cabinets.s2.span-22":{"text":"Voir le détail"},"cabinets.s2.span-23":{"text":"Balance justifiée poste par poste avant révision"},"cabinets.s2.span-24":{"text":"Points d'attention listés par ordre de matérialité"},"cabinets.s2.span-25":{"text":"Journal complet exportable pour le dossier de travail"},"cabinets.s2.span-26":{"text":"Anomalies triées par risque"},"cabinets.s2.span-40":{"text":"Doublons, montants aberrants, TVA incohérente, fournisseurs inhabituels : signalés dès l'import."},"cabinets.s2.span-28":{"text":"Voir le détail"},"cabinets.s2.span-29":{"text":"Comparaison avec l'historique du dossier, pas un seuil arbitraire"},"cabinets.s2.span-30":{"text":"Classement par sévérité : bloquant, à vérifier, informatif"},"cabinets.s2.span-31":{"text":"Alerte au collaborateur en charge, pas à tout le cabinet"},"cabinets.s2.span-32":{"text":"Relance des pièces manquantes"},"cabinets.s2.span-33":{"text":"Ana réclame les justificatifs à vos clients, relance au bon rythme, et vous alerte en cas de blocage."},"cabinets.s2.span-34":{"text":"Voir le détail"},"cabinets.s2.span-35":{"text":"Liste des pièces manquantes établie à partir des flux bancaires"},"cabinets.s2.span-36":{"text":"Relances espacées et personnalisées par client"},"cabinets.s2.span-37":{"text":"Escalade vers le collaborateur après un nombre de rappels que vous fixez"},"cabinets.s3.span-1":{"text":"Le pilote"},"cabinets.s3.h2-2":{"text":"Un pilote pour chiffrer le gain, dossier par dossier."},"cabinets.s3.p-1":{"text":"On démarre sur quelques dossiers représentatifs, on mesure, puis on étend au portefeuille, jamais l'inverse."},"cabinets.s3.span-5":{"text":"Étape 1"},"cabinets.s3.p-2":{"text":"Connexion du portefeuille"},"cabinets.s3.p-3":{"text":"Ana se branche sur votre logiciel de production et sur les flux bancaires de 3 à 5 dossiers pilotes. Aucun changement d'outil pour vos équipes."},"cabinets.s3.span-6":{"text":"Étape 2"},"cabinets.s3.p-4":{"text":"Production assistée"},"cabinets.s3.p-5":{"text":"Saisie, rapprochement et régularisations exécutés par les agents et revus par vos collaborateurs. Chaque correction affine les règles du cabinet."},"cabinets.s3.span-7":{"text":"Étape 3"},"cabinets.s3.p-6":{"text":"Mesure et extension"},"cabinets.s3.p-7":{"text":"Heures récupérées et taux de reprise chiffrés par dossier, puis déploiement progressif au reste du portefeuille."},"cabinets.s4.p-1":{"text":"Vous pilotez une entreprise plutôt qu'un portefeuille de clients ? L'usage direction financière est détaillé à part."},"cabinets.s4.a-1":{"text":"Voir l'usage direction financière","href":"directions-financieres.html"},"cabinets.s5.span-1":{"text":"Ce qui change en cabinet"},"cabinets.s5.p-1":{"text":"Le temps repris sur la production ne disparaît pas : il repart en révision, en conseil, en relation client."},"cabinets.s5.p-2":{"text":"Ana ne remplace pas le jugement du professionnel. Elle lui rend les heures que la saisie lui prenait."},"cabinets.s6.h3-1":{"text":"Passez à la vitesse agentic."},"cabinets.s6.a-1":{"text":"Demander une démo","href":"demo.html"},"cabinets.page.a-4":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5","s6"],"hidden":[]},"seo":{"title":"Ana Finance pour les cabinets d'expertise comptable","description":"Automatisez la saisie, le rapprochement et la révision de vos dossiers clients, sous supervision de vos collaborateurs.","ogTitle":"Ana Finance pour les cabinets d'expertise comptable","ogDescription":"Automatisez la saisie, le rapprochement et la révision de vos dossiers clients, sous supervision de vos collaborateurs.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
