insert into public.page_revisions (page_id, number, kind, content, message)
select id, 1, 'seed', $cms${"fields":{"carrieres.page.a-1":{"text":"Aller au contenu","href":"#main"},"carrieres.header.card_index-1":{"href":"index.html"},"carrieres.s1.span-1":{"text":"Carrières"},"carrieres.s1.h1-1":{"text":"Aucun poste ouvert aujourd'hui, mais les candidatures spontanées sont lues."},"carrieres.s1.p-1":{"text":"Nous sommes une petite équipe et nous ne recrutons pas pour le moment. Cela changera. Si le sujet vous intéresse, écrivez-nous : nous conservons les candidatures et revenons vers les profils pertinents dès qu'un poste s'ouvre."},"carrieres.s2.p-1":{"text":"Candidature spontanée"},"carrieres.s2.h2-1":{"text":"Écrivez-nous, même sans offre en ligne."},"carrieres.s2.p-4":{"html":"Un mot sur ce que vous cherchez, ce que vous savez faire, et pourquoi le sujet vous parle. Un lien vers votre CV ou votre profil suffit, pas besoin de lettre de motivation. Vous pouvez aussi nous écrire à <a href=\"mailto:contact@ana-finance.com?subject=Candidature%20spontan%C3%A9e\" style=\"text-decoration:underline;\">contact@ana-finance.com</a>."},"carrieres.s2.p-5":{"text":"Candidature envoyée."},"carrieres.s2.p-6":{"text":"Nous accusons réception, puis nous vous disons franchement s'il y a un sujet ou non."},"carrieres.s2.button-1":{"text":"Envoyer une autre candidature"},"carrieres.s2.p-7":{"text":"* Champs obligatoires"},"carrieres.s2.span-1":{"text":"*"},"carrieres.s2.span-2":{"text":"Ce champ est obligatoire."},"carrieres.s2.span-3":{"text":"*"},"carrieres.s2.span-4":{"html":"Lien vers votre CV ou votre profil <span style=\"font-weight:400;color:#6b6880;\">(optionnel)</span>"},"carrieres.s2.span-5":{"text":"*"},"carrieres.s2.span-6":{"text":"Ce champ est obligatoire."},"carrieres.s2.a-2":{"text":"politique de confidentialité","href":"mentions-legales.html#confidentialite"},"carrieres.s2.span-7":{"text":"*"},"carrieres.s3.h2-1":{"text":"Les profils qui nous intéresseront en premier"},"carrieres.s3.p-1":{"text":"Ce ne sont pas des offres ouvertes, mais les besoins que nous anticipons. Une candidature sur l'un de ces axes a plus de chances d'être reprise."},"carrieres.s3.span-1":{"text":"Produit & technique"},"carrieres.s3.span-2":{"text":"Ingénierie agents & intégrations"},"carrieres.s3.span-3":{"text":"Concevoir des agents fiables sur des données comptables, et raccorder des systèmes qui n'ont pas été faits pour se parler."},"carrieres.s3.span-4":{"text":"Métier"},"carrieres.s3.span-5":{"text":"Expertise comptable & révision"},"carrieres.s3.span-6":{"text":"Traduire des règles de production en comportements d'agents, et arbitrer ce qui doit rester humain."},"carrieres.s3.span-7":{"text":"Terrain"},"carrieres.s3.span-8":{"text":"Déploiement & réussite client"},"carrieres.s3.span-9":{"text":"Mener des pilotes chez les cabinets et les directions financières, du raccordement à la mesure du gain."},"carrieres.s4.h2-1":{"text":"Comment nous traitons votre candidature"},"carrieres.s4.p-3":{"text":"Nous accusons réception, puis nous vous disons franchement s'il y a un sujet ou non. En l'absence de poste, nous conservons votre candidature pendant deux ans à des fins de recrutement, et vous pouvez demander sa suppression à tout moment en écrivant à contact@ana-finance.com."},"carrieres.s4.p-2":{"text":"Nous ne faisons pas de test technique gratuit ni d'entretien à rallonge : deux échanges, une mise en situation courte, une décision."},"carrieres.s5.h2-1":{"text":"Voyons ce qu'Ana reprendrait chez vous."},"carrieres.s5.p-2":{"text":"Une courte démo, sur vos propres flux : on cartographie les tâches automatisables et le gain attendu."},"carrieres.s5.a-1":{"text":"Demander une démo","href":"demo.html"},"carrieres.page.a-2":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5"],"hidden":[]},"seo":{"title":"Carrières — Ana Finance","description":"Rejoignez l'équipe Ana Finance et participez à l'automatisation supervisée de la finance d'entreprise.","ogTitle":"Carrières — Ana Finance","ogDescription":"Rejoignez l'équipe Ana Finance et participez à l'automatisation supervisée de la finance d'entreprise.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
