select id, 1, 'seed', $cms${"fields":{"comment-ca-marche.page.a-1":{"text":"Aller au contenu","href":"#main"},"comment-ca-marche.header.card_index-1":{"href":"index.html"},"comment-ca-marche.page.a-2":{"text":"Accueil","href":"index.html"},"comment-ca-marche.page.a-3":{"text":"Fonctionnalités","href":"agents.html"},"comment-ca-marche.page.span-1":{"text":"Comment ça marche"},"comment-ca-marche.s1.span-1":{"text":"Comment ça marche"},"comment-ca-marche.s1.h1-1":{"text":"Ce qu'Ana fait, et comment elle le fait."},"comment-ca-marche.s1.p-1":{"text":"Sept tâches reprises par les agents, connectées à vos outils existants en quatre étapes. Aucun projet informatique, aucune migration : vous gardez la validation."},"comment-ca-marche.s1.span-5":{"text":"Pilote de quelques semaines"},"comment-ca-marche.s1.span-3":{"text":"Sans engagement"},"comment-ca-marche.s1.span-4":{"text":"Vous gardez la validation"},"comment-ca-marche.s2.span-1":{"text":"Ce qu'Ana exécute"},"comment-ca-marche.s2.h2-1":{"text":"Sept tâches que vous ne referez plus à la main."},"comment-ca-marche.s2.p-1":{"text":"Choisissez ce que vous voulez voir : le détail des tâches, ou une journée type avec les agents. Cliquez une tâche pour savoir comment Ana procède."},"comment-ca-marche.s2.button-1":{"text":"Les sept tâches"},"comment-ca-marche.s2.button-2":{"text":"Une journée avec Ana"},"comment-ca-marche.s2.span-2":{"text":"Rapprochement bancaire"},"comment-ca-marche.s2.span-3":{"text":"Ana lit les flux bancaires en lecture seule, les associe aux pièces et ne vous remonte que ce qui résiste."},"comment-ca-marche.s2.span-4":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-5":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-6":{"text":"Des heures de pointage ligne par ligne, chaque semaine."},"comment-ca-marche.s2.span-7":{"text":"Avec Ana"},"comment-ca-marche.s2.span-77":{"text":"Rapproché à chaque import, écarts isolés et expliqués."},"comment-ca-marche.s2.span-9":{"text":"Flux récupérés via agrégation DSP2, en lecture seule, aucun ordre de paiement possible"},"comment-ca-marche.s2.span-10":{"text":"Association écriture ↔ pièce y compris sur les paiements partiels ou regroupés"},"comment-ca-marche.s2.span-11":{"text":"Les écarts non résolus arrivent dans votre file avec l'hypothèse la plus probable"},"comment-ca-marche.s2.span-12":{"text":"Relances clients"},"comment-ca-marche.s2.span-13":{"text":"Ana suit les échéances, déclenche les rappels, escalade les cas sensibles et vous laisse la main sur les comptes stratégiques."},"comment-ca-marche.s2.span-14":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-15":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-16":{"text":"Un fichier Excel, des relances oubliées, du retard de paiement."},"comment-ca-marche.s2.span-17":{"text":"Avec Ana"},"comment-ca-marche.s2.span-18":{"text":"Relances envoyées au bon moment, ton adapté au client."},"comment-ca-marche.s2.span-19":{"text":"Suivi des échéances et du comportement de paiement, client par client"},"comment-ca-marche.s2.span-20":{"text":"Séquence de rappels graduée, du rappel courtois à la mise en demeure"},"comment-ca-marche.s2.span-21":{"text":"Les comptes sensibles remontent pour arbitrage : jamais d'envoi à l'aveugle"},"comment-ca-marche.s2.span-22":{"text":"Collecte & saisie des pièces"},"comment-ca-marche.s2.span-23":{"text":"Factures, notes de frais et relevés sont extraits, contrôlés et imputés selon votre plan comptable."},"comment-ca-marche.s2.span-24":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-25":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-26":{"text":"Courir après les justificatifs, ressaisir les factures."},"comment-ca-marche.s2.span-27":{"text":"Avec Ana"},"comment-ca-marche.s2.span-28":{"text":"Pièces récupérées, lues, imputées, rattachées au dossier."},"comment-ca-marche.s2.span-29":{"text":"Extraction quel que soit le format : PDF, photo, e-mail, portail fournisseur"},"comment-ca-marche.s2.span-30":{"text":"Contrôles de cohérence : TVA, mentions obligatoires, doublons, devise"},"comment-ca-marche.s2.span-31":{"text":"Imputation selon votre plan comptable et les habitudes du dossier"},"comment-ca-marche.s2.span-32":{"text":"TVA & déclarations"},"comment-ca-marche.s2.span-33":{"text":"Ana contrôle les taux, les exigibilités et les incohérences, puis prépare la déclaration à valider."},"comment-ca-marche.s2.span-34":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-35":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-36":{"text":"Contrôles manuels dans l'urgence avant échéance."},"comment-ca-marche.s2.span-37":{"text":"Avec Ana"},"comment-ca-marche.s2.span-38":{"text":"Pré-déclaration prête, écarts signalés en amont."},"comment-ca-marche.s2.span-39":{"text":"Contrôle des taux, des exigibilités et des autoliquidations"},"comment-ca-marche.s2.span-40":{"text":"Rapprochement du chiffre d'affaires déclaré et comptabilisé"},"comment-ca-marche.s2.span-41":{"text":"Pré-déclaration prête à valider, écarts signalés avant l'échéance"},"comment-ca-marche.s2.span-42":{"text":"Clôture mensuelle"},"comment-ca-marche.s2.span-78":{"text":"Cut-off, provisions, abonnements récurrents : Ana prépare, justifie, et laisse un journal complet."},"comment-ca-marche.s2.span-44":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-45":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-46":{"text":"Une semaine sous tension, des régularisations à la chaîne."},"comment-ca-marche.s2.span-47":{"text":"Avec Ana"},"comment-ca-marche.s2.span-48":{"text":"Régularisations proposées, dossier bouclé en quelques heures."},"comment-ca-marche.s2.span-49":{"text":"Cut-off des charges et produits, FNP, CCA et provisions proposés"},"comment-ca-marche.s2.span-50":{"text":"Contrats et abonnements récurrents reconnus et étalés automatiquement"},"comment-ca-marche.s2.span-51":{"text":"Chaque écriture porte sa pièce, sa règle et son raisonnement"},"comment-ca-marche.s2.span-52":{"text":"Reporting & trésorerie"},"comment-ca-marche.s2.span-53":{"text":"Trésorerie, runway, écarts budgétaires et note de synthèse prêts à présenter en comité."},"comment-ca-marche.s2.span-54":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-55":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-56":{"text":"Un reporting reconstruit à la main chaque mois."},"comment-ca-marche.s2.span-57":{"text":"Avec Ana"},"comment-ca-marche.s2.span-58":{"text":"Tableau de bord à jour, commentaires rédigés."},"comment-ca-marche.s2.span-79":{"text":"Trésorerie et runway recalculés à chaque import, projection à 3, 6 et 12 mois"},"comment-ca-marche.s2.span-60":{"text":"Écarts réel / budget par poste, commentés en langage clair"},"comment-ca-marche.s2.span-61":{"text":"Export au format attendu par votre comité ou votre client"},"comment-ca-marche.s2.span-62":{"text":"Détection d'anomalies"},"comment-ca-marche.s2.span-80":{"text":"Doublons, montants aberrants, fournisseurs inhabituels, risques de fraude : Ana contrôle chaque import."},"comment-ca-marche.s2.span-64":{"text":"Comment Ana procède"},"comment-ca-marche.s2.span-65":{"text":"Aujourd'hui"},"comment-ca-marche.s2.span-66":{"text":"Les erreurs se découvrent au contrôle, trop tard."},"comment-ca-marche.s2.span-67":{"text":"Avec Ana"},"comment-ca-marche.s2.span-81":{"text":"Alerte dès l'import, triée par sévérité."},"comment-ca-marche.s2.span-69":{"text":"Doublons de facture et montants hors tendance historique"},"comment-ca-marche.s2.span-70":{"text":"Fournisseurs inconnus et changements de coordonnées bancaires"},"comment-ca-marche.s2.span-82":{"text":"Alerte dès l'import, classée par sévérité, avec recommandation de suspendre le paiement si besoin"},"comment-ca-marche.s2.h3-1":{"text":"Le travail est déjà fait quand vous ouvrez votre poste."},"comment-ca-marche.s2.p-13":{"text":"Après chaque import, les agents déroulent leur travail. Vous arrivez sur des décisions, pas sur une pile de saisie."},"comment-ca-marche.s2.span-72":{"text":"07:40"},"comment-ca-marche.s2.p-14":{"text":"Le dernier import est rapproché"},"comment-ca-marche.s2.p-15":{"text":"Ana a intégré les écritures du dernier import, imputé les pièces et placé les quelques écarts restants dans votre file de validation."},"comment-ca-marche.s2.span-73":{"text":"09:15"},"comment-ca-marche.s2.p-5":{"text":"Les relances sont parties"},"comment-ca-marche.s2.p-6":{"text":"Les rappels sont envoyés selon l'ancienneté et l'historique de chaque client ; les dossiers sensibles vous sont remontés pour arbitrage."},"comment-ca-marche.s2.span-74":{"text":"11:00"},"comment-ca-marche.s2.p-7":{"text":"Une anomalie est signalée"},"comment-ca-marche.s2.p-16":{"text":"Un fournisseur facture deux fois la même prestation. Ana signale le doublon, recommande de suspendre le paiement et joint les deux pièces côte à côte."},"comment-ca-marche.s2.span-75":{"text":"14:30"},"comment-ca-marche.s2.p-9":{"text":"La clôture avance seule"},"comment-ca-marche.s2.p-10":{"text":"Provisions et abonnements récurrents sont proposés avec leur justification ; vous validez en lot."},"comment-ca-marche.s2.span-76":{"text":"18:00"},"comment-ca-marche.s2.p-11":{"text":"Le reporting est prêt"},"comment-ca-marche.s2.p-12":{"text":"Trésorerie, runway et écarts budgétaires commentés, exportables pour le comité du lendemain."},"comment-ca-marche.s3.p-1":{"text":"Ana exécute, mais vous décidez du niveau d'autonomie, tâche par tâche."},"comment-ca-marche.s3.a-1":{"text":"Voir le pilotage & contrôle","href":"pilotage-et-controle.html"},"comment-ca-marche.s4.span-1":{"text":"Comment ça se passe"},"comment-ca-marche.s4.h2-1":{"text":"Choisissez une étape pour voir ce qui se passe."},"comment-ca-marche.s4.button-1":{"text":"01, Connexion"},"comment-ca-marche.s4.button-2":{"text":"02, Exécution"},"comment-ca-marche.s4.button-3":{"text":"03, Validation"},"comment-ca-marche.s4.button-4":{"text":"04, Reporting"},"comment-ca-marche.s4.span-2":{"text":"01"},"comment-ca-marche.s4.h3-1":{"text":"Connexion"},"comment-ca-marche.s4.p-1":{"text":"Ana se connecte à vos outils comptables, bancaires et de facturation. Rien à migrer, rien à réinstaller côté équipe."},"comment-ca-marche.s4.span-3":{"text":"Accès bancaire en lecture seule via prestataire agréé DSP2"},"comment-ca-marche.s4.span-4":{"text":"Vos règles et votre plan comptable repris tels quels"},"comment-ca-marche.s4.span-5":{"text":"Une heure de cadrage suffit pour démarrer"},"comment-ca-marche.s4.p-2":{"text":"À retenir"},"comment-ca-marche.s4.p-3":{"text":"Aucun identifiant bancaire ne transite par Ana, et aucun paiement ne peut être initié."},"comment-ca-marche.s4.span-6":{"text":"02"},"comment-ca-marche.s4.h3-2":{"text":"Exécution"},"comment-ca-marche.s4.p-13":{"text":"Les agents traitent la saisie, les rapprochements, les régularisations et les relances à chaque import."},"comment-ca-marche.s4.span-7":{"text":"Chaque action est justifiée par sa pièce source"},"comment-ca-marche.s4.span-8":{"text":"Les cas ambigus sont mis de côté, pas devinés"},"comment-ca-marche.s4.span-9":{"text":"Rien n'est écrit au-delà du niveau d'autonomie que vous avez fixé"},"comment-ca-marche.s4.p-5":{"text":"À retenir"},"comment-ca-marche.s4.p-6":{"text":"Vous réglez ce qu'Ana fait seule, tâche par tâche, et vous pouvez le changer à tout moment."},"comment-ca-marche.s4.span-10":{"text":"03"},"comment-ca-marche.s4.h3-3":{"text":"Validation"},"comment-ca-marche.s4.p-7":{"text":"Vous arbitrez ce qui reste dans une file unique, à l'unité ou par lot. Chaque correction devient une règle proposée."},"comment-ca-marche.s4.span-11":{"text":"Validation en lot sur les séries homogènes"},"comment-ca-marche.s4.span-12":{"text":"Annulation en un clic, sans passer par le support"},"comment-ca-marche.s4.span-13":{"text":"Le taux de reprise baisse dossier après dossier"},"comment-ca-marche.s4.p-8":{"text":"À retenir"},"comment-ca-marche.s4.p-9":{"text":"C'est votre signature au bout de la chaîne : la validation reste humaine, toujours."},"comment-ca-marche.s4.span-14":{"text":"04"},"comment-ca-marche.s4.h3-4":{"text":"Reporting"},"comment-ca-marche.s4.p-10":{"text":"Clôtures, déclarations et reporting de pilotage sont livrés à jour, prêts pour le client, la direction ou le comité."},"comment-ca-marche.s4.span-15":{"text":"Journal complet exportable en CSV et PDF"},"comment-ca-marche.s4.span-16":{"text":"Note de synthèse commentée pour le comité"},"comment-ca-marche.s4.span-18":{"text":"Transmission à l'expert-comptable à chaque clôture"},"comment-ca-marche.s4.p-11":{"text":"À retenir"},"comment-ca-marche.s4.p-12":{"text":"Le rapport est relu, pas reconstruit : le temps passe du montage à l'analyse."},"comment-ca-marche.s5.span-1":{"text":"Le pilote"},"comment-ca-marche.s5.h2-1":{"text":"Ce qu'on vous demande, et ce qu'on vous rend."},"comment-ca-marche.s5.p-1":{"text":"Le pilote se fait sur un périmètre réduit et mesuré. À la fin, vous avez des chiffres, pas une impression."},"comment-ca-marche.s5.span-2":{"text":"De votre côté"},"comment-ca-marche.s5.span-3":{"text":"Trois choses seulement, et rien de lourd."},"comment-ca-marche.s5.span-4":{"text":"Voir le détail"},"comment-ca-marche.s5.span-5":{"text":"Un accès en lecture à vos outils et 3 à 5 dossiers représentatifs"},"comment-ca-marche.s5.span-14":{"text":"Un référent qui valide et corrige au démarrage"},"comment-ca-marche.s5.span-7":{"text":"Une heure de cadrage pour vos règles, seuils et conventions"},"comment-ca-marche.s5.span-8":{"text":"De notre côté"},"comment-ca-marche.s5.span-9":{"text":"Le paramétrage, le suivi et un bilan chiffré."},"comment-ca-marche.s5.span-10":{"text":"Voir le détail"},"comment-ca-marche.s5.span-11":{"text":"Le paramétrage, les connecteurs manquants et la reprise de vos règles"},"comment-ca-marche.s5.span-12":{"text":"Le suivi hebdomadaire du taux de reprise et des heures récupérées"},"comment-ca-marche.s5.span-13":{"text":"Un bilan chiffré en fin de pilote, avant toute généralisation"},"comment-ca-marche.s6.p-1":{"text":"Selon votre structure, le déroulé diffère : le pilote cabinet et le pilote direction financière sont détaillés à part."},"comment-ca-marche.s6.a-1":{"text":"Voir l'usage cabinet","href":"cabinets.html"},"comment-ca-marche.s7.h3-1":{"text":"Passez à la vitesse agentic."},"comment-ca-marche.s7.a-1":{"text":"Demander une démo","href":"demo.html"},"comment-ca-marche.page.a-4":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5","s6","s7"],"hidden":[]},"seo":{"title":"Comment fonctionne Ana Finance — Agents, automatisations et supervision","description":"De la connexion de vos outils à la validation humaine : comment Ana Finance automatise vos tâches financières étape par étape.","ogTitle":"Comment fonctionne Ana Finance — Agents, automatisations et supervision","ogDescription":"De la connexion de vos outils à la validation humaine : comment Ana Finance automatise vos tâches financières étape par étape.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
