:{"text":"Comptes bancaires (DSP2)"},"connecteurs.s2.span-7":{"text":"Accès en lecture seule aux mouvements et aux soldes, via prestataire agréé."},"connecteurs.s2.span-8":{"text":"Voir en grand"},"connecteurs.s2.li-5":{"html":"<strong>Sens :</strong> lecture seule. Ana ne peut initier aucun paiement."},"connecteurs.s2.li-33":{"html":"<strong>Fréquence prévue :</strong> plusieurs synchronisations par jour, selon la banque."},"connecteurs.s2.li-7":{"html":"<strong>Données :</strong> soldes, mouvements, libellés, références de virement, catégorisation."},"connecteurs.s2.li-8":{"html":"<strong>Garde-fou :</strong> consentement DSP2 renouvelable et révocable à tout moment."},"connecteurs.s2.span-9":{"text":"Ventes"},"connecteurs.s2.span-32":{"text":"Prévu"},"connecteurs.s2.span-10":{"text":"Facturation & encaissement"},"connecteurs.s2.span-11":{"text":"Récupération des factures émises et de leur statut de paiement."},"connecteurs.s2.span-12":{"text":"Voir en grand"},"connecteurs.s2.li-9":{"html":"<strong>Sens :</strong> lecture des factures, écriture du statut de relance."},"connecteurs.s2.li-34":{"html":"<strong>Fréquence prévue :</strong> à chaque nouvelle facture quand l'outil le permet, sinon à intervalle régulier."},"connecteurs.s2.li-11":{"html":"<strong>Données :</strong> factures, avoirs, échéances, clients, encaissements, moyens de paiement."},"connecteurs.s2.li-12":{"html":"<strong>Garde-fou :</strong> Ana ne modifie ni n'annule jamais une facture émise."},"connecteurs.s2.span-13":{"text":"Opérations"},"connecteurs.s2.span-33":{"text":"Prévu"},"connecteurs.s2.span-14":{"text":"ERP & gestion commerciale"},"connecteurs.s2.span-15":{"text":"Alignement des commandes, réceptions et achats avec les pièces comptables."},"connecteurs.s2.span-16":{"text":"Voir en grand"},"connecteurs.s2.li-13":{"html":"<strong>Sens :</strong> lecture. Les écritures partent vers le logiciel comptable, pas vers l'ERP."},"connecteurs.s2.li-35":{"html":"<strong>Fréquence prévue :</strong> synchronisation quotidienne, ou à la demande avant clôture."},"connecteurs.s2.li-15":{"html":"<strong>Données :</strong> commandes, bons de réception, achats, stocks valorisés, analytique."},"connecteurs.s2.li-16":{"html":"<strong>Garde-fou :</strong> périmètre limité aux entités et axes analytiques que vous ouvrez."},"connecteurs.s2.span-17":{"text":"Achats"},"connecteurs.s2.span-34":{"text":"Prévu"},"connecteurs.s2.span-18":{"text":"Notes de frais & cartes"},"connecteurs.s2.span-19":{"text":"Collecte des justificatifs et rapprochement avec les débits carte."},"connecteurs.s2.span-20":{"text":"Voir en grand"},"connecteurs.s2.li-17":{"html":"<strong>Sens :</strong> lecture des dépenses, écriture du statut de traitement."},"connecteurs.s2.li-36":{"html":"<strong>Fréquence prévue :</strong> à chaque nouvelle dépense."},"connecteurs.s2.li-19":{"html":"<strong>Données :</strong> justificatifs, montants, TVA, affectation collaborateur et projet."},"connecteurs.s2.li-20":{"html":"<strong>Garde-fou :</strong> les dépenses sans justificatif sont signalées, jamais comptabilisées d'office."},"connecteurs.s2.span-21":{"text":"Social"},"connecteurs.s2.span-35":{"text":"Prévu"},"connecteurs.s2.span-22":{"text":"Paie & RH"},"connecteurs.s2.span-23":{"text":"Reprise des journaux de paie pour l'écriture et le reporting."},"connecteurs.s2.span-24":{"text":"Voir en grand"},"connecteurs.s2.li-21":{"html":"<strong>Sens :</strong> lecture du journal de paie consolidé."},"connecteurs.s2.li-37":{"html":"<strong>Fréquence prévue :</strong> mensuelle, après clôture de la paie."},"connecteurs.s2.li-23":{"html":"<strong>Données :</strong> journal comptable de paie, charges, effectifs agrégés."},"connecteurs.s2.li-24":{"html":"<strong>Garde-fou :</strong> aucune donnée individuelle de rémunération n'est traitée par les agents."},"connecteurs.s2.span-25":{"text":"API"},"connecteurs.s2.span-36":{"text":"Étudié pendant le pilote"},"connecteurs.s2.span-26":{"text":"Connecteur sur mesure"},"connecteurs.s2.span-27":{"text":"Pour un outil interne ou un logiciel absent de la liste."},"connecteurs.s2.span-28":{"text":"Voir en grand"},"connecteurs.s2.li-25":{"html":"<strong>Sens :</strong> défini avec vous, périmètre minimal par défaut."},"connecteurs.s2.li-38":{"html":"<strong>Fréquence :</strong> planifiée, ou à chaque dépôt de fichier."},"connecteurs.s2.li-27":{"html":"<strong>Données :</strong> API REST, dépôt de fichiers, SFTP, base en lecture seule."},"connecteurs.s2.li-28":{"html":"<strong>Délai :</strong> à cadrer lors du pilote selon la complexité."},"connecteurs.s3.p-2":{"text":"Aujourd'hui, Ana fonctionne avec tout logiciel qui exporte un FEC. Les connecteurs marqués « Prévu » ne sont pas encore disponibles : leur calendrier vous est présenté lors du cadrage. Si votre outil n'y figure pas, un connecteur sur mesure est étudié pendant le pilote."},"connecteurs.s4.h2-1":{"text":"Voyons ce qu'Ana reprendrait chez vous."},"connecteurs.s4.p-2":{"text":"Une courte démo, sur vos propres flux : on cartographie les tâches automatisables et le gain attendu."},"connecteurs.s4.a-1":{"text":"Demander une démo","href":"demo.html"},"connecteurs.page.a-4":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4"],"hidden":[]},"seo":{"title":"Connecteurs et intégrations — Ana Finance","description":"Statut, sens, fréquence et données de chaque connecteur Ana Finance : import du FEC disponible aujourd'hui, connexions bancaires et de gestion prévues.","ogTitle":"Connecteurs et intégrations — Ana Finance","ogDescription":"Statut, sens, fréquence et données de chaque connecteur Ana Finance : import du FEC disponible aujourd'hui, connexions bancaires et de gestion prévues.","ogImage":null,"canonical":"","noindex":false,"rev":1}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
