select id, 1, 'seed', $cms${"fields":{"index.page.a-1":{"text":"Aller au contenu","href":"#main"},"index.s1.span-1":{"text":"Agents IA pour la finance"},"index.s1.h1-1":{"text":"Vos meilleurs profils passent leurs journées à ressaisir."},"index.s1.p-1":{"text":"Collecte de pièces, rapprochements, relances, reporting : la production récurrente absorbe le temps que vous voudriez passer en révision, en analyse et en conseil. Ana déploie des agents IA qui la reprennent, sous votre contrôle."},"index.s1.a-1":{"text":"Demander une démo","href":"demo.html"},"index.s1.a-2":{"text":"Comment ça marche","href":"#fonctionnement"},"index.s1.span-2":{"text":"Données hébergées dans l'UE"},"index.s1.span-3":{"text":"Validation humaine sur chaque action"},"index.s1.span-4":{"text":"Décisions traçables et réversibles"},"index.s2.slot-1":{"src":"","alt":"Capture d'écran : file de validation Ana (agents, actions en attente, journal)"},"index.s3.p-1":{"text":"Déjà testé par des cabinets et des directions financières"},"index.s3.slot-1":{"src":"","alt":"Logo client 1"},"index.s3.slot-2":{"src":"","alt":"Logo client 2"},"index.s3.slot-3":{"src":"","alt":"Logo client 3"},"index.s3.slot-4":{"src":"","alt":"Logo client 4"},"index.s4.span-1":{"text":"Comment ça marche"},"index.s4.h2-1":{"text":"Une chaîne d'agents branchée sur vos outils, pas un logiciel de plus."},"index.s4.p-1":{"text":"Aucune migration, aucune reprise d'historique. Ana lit vos flux existants, exécute ce que vous lui confiez, et vous rend la main à chaque écriture."},"index.s4.span-2":{"text":"01 INGESTION"},"index.s4.span-3":{"text":"Flux connectés"},"index.s4.span-4":{"text":"Banques DSP2, factures, logiciel comptable, ERP."},"index.s4.span-5":{"text":"02 RAISONNEMENT"},"index.s4.span-6":{"text":"Agents spécialisés"},"index.s4.span-7":{"text":"Un agent par tâche, avec vos règles de gestion."},"index.s4.span-8":{"text":"03 CONTRÔLE"},"index.s4.span-9":{"text":"Validation humaine"},"index.s4.span-10":{"text":"Trois niveaux d'autonomie, au choix, par tâche."},"index.s4.span-11":{"text":"04 RESTITUTION"},"index.s4.span-12":{"text":"Écritures & reporting"},"index.s4.span-13":{"text":"Poussées dans vos outils, journal complet à l'appui."},"index.s4.span-14":{"text":"Agent Control supervise les six agents"},"index.s4.span-15":{"text":"Il rejoue leurs décisions, signale les écarts, et garde tout réversible."},"index.s4.a-1":{"text":"Voir le schéma complet","href":"agents.html"},"index.s4.p-2":{"text":"Ce que les agents exécutent"},"index.s4.span-16":{"text":"Collecte des pièces"},"index.s4.span-17":{"text":"Factures, relevés, justificatifs récupérés et lus automatiquement, manquants relancés."},"index.s4.span-18":{"text":"Rapprochement bancaire"},"index.s4.span-28":{"text":"Lettrage des mouvements aux pièces, écarts signalés dès l'import."},"index.s4.span-20":{"text":"Relances clients"},"index.s4.span-21":{"text":"Scénario de relance déroulé, arrêté dès le paiement, litiges remontés."},"index.s4.span-22":{"text":"TVA & déclaratif"},"index.s4.span-23":{"text":"Cohérence des taux contrôlée, bases préparées, dépôt laissé au professionnel."},"index.s4.span-24":{"text":"Clôture"},"index.s4.span-25":{"text":"Checklist déroulée, écritures récurrentes préparées, blocages remontés."},"index.s4.span-26":{"text":"Reporting de gestion"},"index.s4.span-27":{"text":"Tableaux de bord et points de trésorerie mis à jour et diffusés."},"index.s4.a-2":{"text":"Voir le détail des automatisations →","href":"comment-ca-marche.html#taches"},"index.s5.span-1":{"text":"La question qu'on nous pose en premier"},"index.s5.h2-1":{"text":"Ana ne signe pas vos comptes."},"index.s5.p-1":{"text":"Confier de la production à une IA n'a de sens que si vous pouvez vérifier ce qu'elle a fait, et revenir en arrière. Ana prépare et propose ; la validation, la signature et la responsabilité restent celles du professionnel. Quatre garde-fous rendent cela vrai en pratique."},"index.s5.p-2":{"text":"Trois niveaux d'autonomie"},"index.s5.p-3":{"text":"Observation, validation, ou autonome sous un seuil que vous fixez. Réglable par tâche et par dossier."},"index.s5.p-4":{"text":"Rien d'irréversible"},"index.s5.p-5":{"text":"Chaque action est journalisée avec son état antérieur. Toute écriture peut être annulée."},"index.s5.p-6":{"text":"Tout est explicable"},"index.s5.p-7":{"text":"Pour chaque décision : la pièce, la règle appliquée, l'horodatage. Pas de boîte noire."},"index.s5.p-8":{"text":"Le calcul avant le texte"},"index.s5.p-9":{"text":"Les montants viennent d'un moteur déterministe. L'IA rédige et explique, elle n'invente jamais un chiffre."},"index.s5.a-1":{"text":"Voir le pilotage et les contrôles →","href":"pilotage-et-controle.html"},"index.s6.span-1":{"text":"Cas d'usage"},"index.s6.h2-1":{"text":"Le même moteur, trois façons de s'en servir."},"index.s6.p-2":{"text":"Un cabinet cherche à absorber un portefeuille, une direction financière à piloter sur des chiffres à jour, une PME à y voir clair sans équipe dédiée. Chacun démarre par un pilote sur son propre périmètre."},"index.s6.card_cabinets-1":{"href":"cabinets.html"},"index.s6.span-2":{"text":"Cabinets comptables"},"index.s6.span-3":{"text":"Absorber la production du portefeuille"},"index.s6.span-4":{"text":"Reprendre la saisie et le rapprochement dossier par dossier, pour rendre du temps à la révision et au conseil."},"index.s6.span-5":{"text":"Découvrir →"},"index.s6.card_directions_financieres-1":{"href":"directions-financieres.html"},"index.s6.span-6":{"text":"Directions financières"},"index.s6.span-7":{"text":"Piloter sur des chiffres à jour"},"index.s6.span-14":{"text":"Clôtures raccourcies, reporting remis à jour à chaque import, écarts repérés pendant le mois plutôt qu'après."},"index.s6.span-9":{"text":"Découvrir →"},"index.s6.card_pme_et_startups-1":{"href":"pme-et-startups.html"},"index.s6.span-10":{"text":"PME & startups"},"index.s6.span-11":{"text":"Un contrôle de gestion sans équipe"},"index.s6.span-12":{"text":"Marge, budget et trésorerie suivis automatiquement, sans recruter et sans changer d'expert-comptable."},"index.s6.span-13":{"text":"Découvrir →"},"index.s7.span-1":{"text":"Collaborateurs"},"index.s7.span-2":{"text":"Le temps rendu"},"index.s7.span-3":{"text":"Saisie et rapprochement déjà faits, à vérifier plutôt qu'à produire."},"index.s7.span-4":{"text":"Managers"},"index.s7.span-5":{"text":"L'avancement sans le relancer"},"index.s7.span-10":{"text":"L'état de chaque dossier consultable à tout moment, les blocages remontés seuls."},"index.s7.span-7":{"text":"Direction"},"index.s7.span-8":{"text":"Le contrôle et la preuve"},"index.s7.span-9":{"text":"Décisions journalisées et réversibles, hébergement UE, RGPD dès la conception."},"index.s8.span-1":{"text":"Pas encore prêt pour une démo ?"},"index.s8.h2-1":{"text":"Estimez le temps que vous récupéreriez."},"index.s8.p-1":{"text":"Une estimation indicative, à partir du nombre de dossiers et du temps de production actuel — sans formulaire."},"index.s8.span-3":{"text":"récupérées par mois"},"index.s8.span-4":{"text":"Hypothèse : les agents reprennent 55 % du temps de production. Estimation indicative, à affiner sur vos dossiers."},"index.s9.h2-1":{"text":"Passez à la vitesse agentic."},"index.s9.p-2":{"text":"Une courte démo sur vos propres flux : on cartographie les tâches automatisables et le temps que vous récupérez."},"index.s9.a-1":{"text":"Demander une démo","href":"demo.html"},"index.page.a-2":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5","s6","s7","s8","s9"],"hidden":[]},"seo":{"title":"Ana Finance — Agents IA pour la finance, sous contrôle humain","description":"Des agents IA reprennent factures, rapprochements et reporting de votre cabinet ou direction financière. Supervisés, réversibles, hébergés en Europe.","ogTitle":"Ana Finance — Agents IA pour la finance, sous contrôle humain","ogDescription":"Des agents IA reprennent factures, rapprochements et reporting de votre cabinet ou direction financière. Supervisés, réversibles, hébergés en Europe.","ogImage":null,"canonical":"","noindex":false,"rev":1}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
