insert into public.page_revisions (page_id, number, kind, content, message)
select id, 1, 'seed', $cms${"fields":{"mentions-legales.page.a-1":{"text":"Aller au contenu","href":"#main"},"mentions-legales.header.card_index-1":{"href":"index.html"},"mentions-legales.s1.span-1":{"text":"Informations légales"},"mentions-legales.s1.h1-1":{"text":"Mentions légales, confidentialité et conditions."},"mentions-legales.s1.p-2":{"text":"Qui édite ce site, comment vos données personnelles sont traitées et dans quelles conditions le service est fourni. Dernière mise à jour : novembre 2026."},"mentions-legales.s2.span-1":{"text":"Mentions légales"},"mentions-legales.s2.h2-1":{"text":"Éditeur du site"},"mentions-legales.s2.h3-1":{"text":"Éditeur"},"mentions-legales.s2.p-6":{"text":"Le site ana-finance.com est édité par Ana Finance, société par actions simplifiée en cours d'immatriculation au registre du commerce et des sociétés. Son numéro d'immatriculation, le montant de son capital, l'adresse de son siège et son numéro de TVA intracommunautaire seront publiés sur cette page dès l'immatriculation."},"mentions-legales.s2.p-7":{"html":"Directeurs de la publication : Romain Innocenzi et Marco Stefanovic, cofondateurs. Contact : <a href=\"mailto:contact@ana-finance.com\" style=\"text-decoration:underline;\">contact@ana-finance.com</a>."},"mentions-legales.s2.h3-2":{"text":"Hébergement"},"mentions-legales.s2.p-8":{"text":"Le site est hébergé par GitHub, Inc. (service GitHub Pages), 88 Colin P. Kelly Jr. Street, San Francisco, CA 94107, États-Unis. Les demandes envoyées par les formulaires du site sont enregistrées dans une base de données fournie par Supabase et hébergée dans l'Union européenne, en Irlande."},"mentions-legales.s2.h3-3":{"text":"Propriété intellectuelle"},"mentions-legales.s2.p-4":{"text":"L'ensemble des contenus du site (textes, visuels, logo, interfaces) est la propriété d'Ana Finance ou de ses partenaires. Toute reproduction sans autorisation écrite est interdite."},"mentions-legales.s2.h3-4":{"text":"Nature du service"},"mentions-legales.s2.p-5":{"text":"Ana Finance édite un outil d'automatisation destiné aux professionnels. Il ne se substitue ni à l'expert-comptable ni au commissaire aux comptes et ne constitue pas un conseil comptable, fiscal ou juridique."},"mentions-legales.s3.span-1":{"text":"Confidentialité"},"mentions-legales.s3.h2-1":{"text":"Politique de protection des données"},"mentions-legales.s3.h3-1":{"text":"Responsable de traitement"},"mentions-legales.s3.p-9":{"html":"Pour les données collectées via ce site (demandes de démonstration, de contact et candidatures), le responsable de traitement est Ana Finance, société en cours d'immatriculation, représentée par ses cofondateurs. Ana Finance n'a pas désigné de délégué à la protection des données : pour toute question sur vos données personnelles, écrivez à <a href=\"mailto:contact@ana-finance.com\" style=\"text-decoration:underline;\">contact@ana-finance.com</a>."},"mentions-legales.s3.h3-2":{"text":"Finalités et bases légales"},"mentions-legales.s3.p-10":{"text":"Répondre aux demandes de démonstration, de contact ou de rendez-vous (intérêt légitime et mesures précontractuelles) ; étudier les candidatures reçues (mesures précontractuelles) ; suivre la fréquentation du site sous forme de statistiques anonymes (intérêt légitime) ; respecter nos obligations légales et comptables (obligation légale)."},"mentions-legales.s3.h3-3":{"text":"Données traitées et durées"},"mentions-legales.s3.p-11":{"text":"Identité, coordonnées professionnelles et contenu de votre message : conservés 24 mois à compter du dernier contact. Candidatures : conservées deux ans, sauf demande de suppression de votre part. Mesure d'audience : statistiques agrégées, sans donnée permettant de vous identifier."},"mentions-legales.s3.h3-4":{"text":"Destinataires et sous-traitants"},"mentions-legales.s3.p-12":{"text":"Vos données sont accessibles aux seules personnes d'Ana Finance chargées de vous répondre. Elles sont enregistrées chez notre prestataire de base de données, Supabase, dans l'Union européenne (Irlande). Le site est servi par GitHub (GitHub Pages), société américaine, qui traite à ce titre des données techniques de connexion, dont votre adresse IP. Aucune donnée n'est cédée ni vendue."},"mentions-legales.s3.h3-5":{"text":"Données clients traitées dans la plateforme"},"mentions-legales.s3.p-13":{"text":"Dans le cadre du service, Ana Finance agit comme sous-traitant au sens de l'article 28 du RGPD : un accord de sous-traitance encadre les traitements, les mesures de sécurité et les durées de conservation. Lorsqu'une connexion bancaire est mise en place, elle s'effectue en lecture seule via un prestataire agréé DSP2, après consentement explicite."},"mentions-legales.s3.h3-6":{"text":"Intelligence artificielle"},"mentions-legales.s3.p-6":{"text":"Les traitements reposent sur des systèmes d'IA sous supervision humaine. Chaque action d'agent est journalisée, explicable et réversible ; aucune décision définitive n'est prise sans validation humaine."},"mentions-legales.s3.h3-7":{"text":"Vos droits"},"mentions-legales.s3.p-14":{"html":"Vous disposez des droits d'accès, de rectification, d'effacement, de limitation, d'opposition et de portabilité. Écrivez à <a href=\"mailto:contact@ana-finance.com\" style=\"text-decoration:underline;\">contact@ana-finance.com</a>. Vous pouvez également saisir la CNIL (3 place de Fontenoy, 75007 Paris)."},"mentions-legales.s3.h3-8":{"text":"Cookies"},"mentions-legales.s3.p-15":{"text":"Ce site ne dépose aucun cookie et n'utilise aucun traceur publicitaire : il n'affiche donc pas de bandeau de consentement. La mesure d'audience, lorsqu'elle est active, repose sur Plausible Analytics, hébergé dans l'Union européenne, qui fonctionne sans cookie et ne collecte aucune donnée permettant de vous identifier."},"mentions-legales.s4.span-1":{"text":"CGU / CGV"},"mentions-legales.s4.h2-1":{"text":"Conditions d'utilisation et de vente"},"mentions-legales.s4.h3-1":{"text":"Objet"},"mentions-legales.s4.p-1":{"text":"Les présentes conditions régissent l'accès au site et la fourniture de la plateforme Ana Finance aux clients professionnels. Toute commande implique leur acceptation sans réserve."},"mentions-legales.s4.h3-2":{"text":"Accès au service"},"mentions-legales.s4.p-8":{"text":"L'accès à la plateforme est réservé aux professionnels, dans le cadre d'un pilote ou d'un abonnement en cours. Les identifiants sont personnels ; le client est responsable de leur confidentialité et des actions réalisées depuis son compte."},"mentions-legales.s4.h3-3":{"text":"Obligations du client"},"mentions-legales.s4.p-3":{"text":"Le client garantit disposer des droits nécessaires sur les données transmises et assure la revue des travaux produits par les agents avant toute utilisation comptable, fiscale ou déclarative."},"mentions-legales.s4.h3-4":{"text":"Prix et facturation"},"mentions-legales.s4.p-9":{"text":"Les prix sont établis sur devis, selon le périmètre, le nombre de dossiers et les connecteurs requis. Ils sont exprimés hors taxes et facturés selon la périodicité indiquée au devis. Sauf mention contraire au devis, les factures sont payables par virement à 30 jours à compter de leur date d'émission. Tout retard de paiement donne lieu à des pénalités calculées au taux d'intérêt appliqué par la Banque centrale européenne à son opération de refinancement la plus récente, majoré de 10 points, ainsi qu'à une indemnité forfaitaire de 40 euros pour frais de recouvrement."},"mentions-legales.s4.h3-5":{"text":"Durée et résiliation"},"mentions-legales.s4.p-5":{"text":"L'abonnement est conclu pour la durée indiquée au devis et renouvelable par tacite reconduction, sauf dénonciation dans le préavis prévu. Les modalités de réversibilité et de restitution des données figurent au contrat."},"mentions-legales.s4.h3-6":{"text":"Responsabilité"},"mentions-legales.s4.p-6":{"text":"Ana Finance fournit un outil d'automatisation sous supervision humaine et ne saurait être tenue responsable des décisions comptables, fiscales ou de gestion prises par le client. La responsabilité est limitée aux montants prévus au contrat."},"mentions-legales.s4.h3-7":{"text":"Droit applicable"},"mentions-legales.s4.p-10":{"text":"Les présentes conditions sont soumises au droit français. En cas de litige, et après tentative de résolution amiable, les tribunaux du ressort du siège social d'Ana Finance sont seuls compétents."},"mentions-legales.footer.a-15":{"text":"Mentions légales","href":"#mentions-legales"},"mentions-legales.footer.a-16":{"text":"Politique de confidentialité","href":"#confidentialite"},"mentions-legales.footer.a-17":{"text":"CGU / CGV","href":"#cgu"},"mentions-legales.page.a-2":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4"],"hidden":[]},"seo":{"title":"Mentions légales — Ana Finance","description":"Mentions légales, conditions d'utilisation et politique de confidentialité d'Ana Finance.","ogTitle":"Mentions légales — Ana Finance","ogDescription":"Mentions légales, conditions d'utilisation et politique de confidentialité d'Ana Finance.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
