select id, 1, 'seed', $cms${"fields":{"pilotage-et-controle.page.a-1":{"text":"Aller au contenu","href":"#main"},"pilotage-et-controle.header.card_index-1":{"href":"index.html"},"pilotage-et-controle.page.a-2":{"text":"Accueil","href":"index.html"},"pilotage-et-controle.page.a-3":{"text":"Fonctionnalités","href":"agents.html"},"pilotage-et-controle.page.span-1":{"text":"Pilotage & contrôle"},"pilotage-et-controle.s1.span-1":{"text":"Pilotage & contrôle"},"pilotage-et-controle.s1.h1-1":{"text":"Automatiser ne veut pas dire lâcher le contrôle."},"pilotage-et-controle.s1.p-1":{"text":"C'est votre signature au bout de la chaîne. Ana travaille donc sous des règles que vous fixez, journalise chacune de ses actions, et ne fait rien d'irréversible."},"pilotage-et-controle.s1.span-2":{"text":"Validation par lot"},"pilotage-et-controle.s1.span-3":{"text":"Journal exportable"},"pilotage-et-controle.s1.span-4":{"text":"Annulation en un clic"},"pilotage-et-controle.s2.span-1":{"text":"Trois niveaux d'autonomie"},"pilotage-et-controle.s2.h2-1":{"text":"Vous choisissez ce qu'Ana fait seule."},"pilotage-et-controle.s2.p-1":{"text":"Le réglage se fait par type de tâche et par dossier, et se change à tout moment. Cliquez un niveau pour voir le partage exact des rôles."},"pilotage-et-controle.s2.button-4":{"text":"Niveau 1, Observation"},"pilotage-et-controle.s2.button-5":{"text":"Niveau 2, Validation"},"pilotage-et-controle.s2.button-6":{"text":"Niveau 3, Autonome sous seuil"},"pilotage-et-controle.s2.h3-4":{"text":"Ana observe et propose, rien n'est écrit."},"pilotage-et-controle.s2.p-11":{"text":"Ana montre ce qu'elle ferait, sans rien enregistrer. C'est le réglage de départ : il sert à calibrer vos règles sur un dossier avant de lui confier quoi que ce soit."},"pilotage-et-controle.s2.p-3":{"text":"Ce que fait Ana"},"pilotage-et-controle.s2.span-20":{"text":"Prépare l'écriture, la relance ou la déclaration, sans l'enregistrer"},"pilotage-et-controle.s2.span-3":{"text":"Explique la règle appliquée et joint la pièce"},"pilotage-et-controle.s2.span-21":{"text":"Mesure l'écart entre ses propositions et votre pratique"},"pilotage-et-controle.s2.p-4":{"text":"Ce qui vous revient"},"pilotage-et-controle.s2.span-22":{"text":"Comparez ses propositions à ce que vous auriez fait"},"pilotage-et-controle.s2.span-6":{"text":"Corrigez : la correction devient une règle proposée"},"pilotage-et-controle.s2.span-23":{"text":"Passez au niveau 2 quand ses propositions vous conviennent"},"pilotage-et-controle.s2.h3-5":{"text":"Ana propose, vous validez."},"pilotage-et-controle.s2.p-12":{"text":"Chaque action attend votre accord dans la file de validation : rien n'est écrit sans vous. C'est le réglage de la plupart des équipes, et celui qu'on garde sur les dossiers sensibles."},"pilotage-et-controle.s2.p-6":{"text":"Ce que fait Ana"},"pilotage-et-controle.s2.span-24":{"text":"Prépare l'écriture, la relance ou la déclaration"},"pilotage-et-controle.s2.span-25":{"text":"Explique la règle appliquée et joint la pièce"},"pilotage-et-controle.s2.span-26":{"text":"Classe les propositions par urgence dans votre file"},"pilotage-et-controle.s2.p-7":{"text":"Ce qui vous revient"},"pilotage-et-controle.s2.span-27":{"text":"Validez à l'unité ou par lot"},"pilotage-et-controle.s2.span-28":{"text":"Corrigez : la correction devient une règle proposée"},"pilotage-et-controle.s2.span-29":{"text":"Rien ne part, rien ne s'écrit sans votre clic"},"pilotage-et-controle.s2.h3-6":{"text":"Ana exécute sous le seuil que vous fixez."},"pilotage-et-controle.s2.p-13":{"text":"Vous définissez un montant, un niveau de confiance ou un type de pièce. En dessous, Ana écrit et vous rend compte ; au-dessus, elle repasse en validation."},"pilotage-et-controle.s2.p-9":{"text":"Ce que fait Ana"},"pilotage-et-controle.s2.span-30":{"text":"Exécute ce qui est sous le seuil et vous le notifie"},"pilotage-et-controle.s2.span-31":{"text":"Renvoie en validation tout ce qui dépasse, avec son analyse"},"pilotage-et-controle.s2.span-32":{"text":"Trace chaque décision et le seuil qui l'a autorisée"},"pilotage-et-controle.s2.p-10":{"text":"Ce qui vous revient"},"pilotage-et-controle.s2.span-33":{"text":"Fixez les seuils par tâche et par dossier"},"pilotage-et-controle.s2.span-18":{"text":"Annulez en un clic, à l'unité ou par lot"},"pilotage-et-controle.s2.span-34":{"text":"Repassez au niveau 1 ou 2 sur un dossier en une action"},"pilotage-et-controle.s3.span-1":{"text":"Les garde-fous"},"pilotage-et-controle.s3.h2-1":{"text":"Chaque action est justifiée, traçable et réversible."},"pilotage-et-controle.s3.p-1":{"text":"Cliquez une bulle pour voir ce que ça donne concrètement."},"pilotage-et-controle.s3.span-2":{"text":"File de validation"},"pilotage-et-controle.s3.span-3":{"text":"Une seule file pour tout ce qui attend un arbitrage, triée par urgence et par risque."},"pilotage-et-controle.s3.span-4":{"text":"Voir le détail"},"pilotage-et-controle.s3.span-5":{"text":"Regroupement des séries homogènes pour une validation en lot"},"pilotage-et-controle.s3.span-6":{"text":"Tri par montant, par dossier ou par niveau de risque"},"pilotage-et-controle.s3.span-7":{"text":"Rien ne se perd : une action non traitée reste en file avec son ancienneté"},"pilotage-et-controle.s3.span-8":{"text":"Journal explicable"},"pilotage-et-controle.s3.span-9":{"text":"Pour chaque écriture : la pièce source, la règle appliquée et le raisonnement de l'agent."},"pilotage-et-controle.s3.span-10":{"text":"Voir le détail"},"pilotage-et-controle.s3.span-11":{"text":"Historique horodaté par dossier, par utilisateur et par agent"},"pilotage-et-controle.s3.span-12":{"text":"Export CSV et PDF pour vos contrôles internes"},"pilotage-et-controle.s3.span-13":{"text":"Aucune action anonyme : chaque ligne porte son auteur"},"pilotage-et-controle.s3.span-14":{"text":"Réversibilité intégrale"},"pilotage-et-controle.s3.span-15":{"text":"Toute action se défait en un clic, à l'unité ou par lot, sans passer par le support."},"pilotage-et-controle.s3.span-16":{"text":"Voir le détail"},"pilotage-et-controle.s3.span-17":{"text":"Annulation d'une écriture, d'un lot ou d'une journée entière"},"pilotage-et-controle.s3.span-18":{"text":"Les pièces et lettrages reviennent à leur état antérieur"},"pilotage-et-controle.s3.span-19":{"text":"L'annulation est elle aussi journalisée"},"pilotage-et-controle.s3.span-20":{"text":"Vos règles, vos seuils"},"pilotage-et-controle.s3.span-21":{"text":"Plan comptable, conventions, seuils de matérialité : Ana s'aligne sur votre méthode."},"pilotage-et-controle.s3.span-22":{"text":"Voir le détail"},"pilotage-et-controle.s3.span-23":{"text":"Reprise de votre plan comptable et de vos schémas d'imputation"},"pilotage-et-controle.s3.span-24":{"text":"Règles par dossier, par client ou par entité"},"pilotage-et-controle.s3.span-25":{"text":"Conventions de nommage et de lettrage respectées"},"pilotage-et-controle.s3.span-26":{"text":"Apprentissage de vos corrections"},"pilotage-et-controle.s3.span-27":{"text":"Chaque correction devient une règle proposée : le taux de reprise baisse dossier après dossier."},"pilotage-et-controle.s3.span-28":{"text":"Voir le détail"},"pilotage-et-controle.s3.span-29":{"text":"La correction est proposée comme règle, pas appliquée en silence"},"pilotage-et-controle.s3.span-30":{"text":"Vous acceptez, ajustez ou refusez la règle"},"pilotage-et-controle.s3.span-31":{"text":"Suivi du taux de reprise semaine après semaine"},"pilotage-et-controle.s3.span-32":{"text":"Sécurité & hébergement"},"pilotage-et-controle.s3.span-33":{"text":"Données hébergées dans l'Union européenne, accès bancaire en lecture seule, droits par utilisateur."},"pilotage-et-controle.s3.span-34":{"text":"Voir le détail"},"pilotage-et-controle.s3.span-35":{"text":"Agrégation bancaire via un prestataire agréé DSP2, sans pouvoir de paiement"},"pilotage-et-controle.s3.span-36":{"text":"Droits par utilisateur, par dossier et par type d'action"},"pilotage-et-controle.s3.span-37":{"text":"Chiffrement en transit et au repos, sauvegardes dans l'UE"},"pilotage-et-controle.s4.p-1":{"text":"Voir les tâches concrètes qui passent par ces garde-fous."},"pilotage-et-controle.s4.a-1":{"text":"Voir les automatisations","href":"comment-ca-marche.html#taches"},"pilotage-et-controle.s5.h3-1":{"text":"Passez à la vitesse agentic."},"pilotage-et-controle.s5.a-1":{"text":"Demander une démo","href":"demo.html"},"pilotage-et-controle.page.a-4":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5"],"hidden":[]},"seo":{"title":"Pilotage et contrôle financier — Ana Finance","description":"Niveaux d'autonomie, file de validation, journal explicable et annulation en un clic : gardez le contrôle sur ce que font les agents Ana.","ogTitle":"Pilotage et contrôle financier — Ana Finance","ogDescription":"Niveaux d'autonomie, file de validation, journal explicable et annulation en un clic : gardez le contrôle sur ce que font les agents Ana.","ogImage":null,"canonical":"","noindex":false,"rev":1}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
