insert into public.page_revisions (page_id, number, kind, content, message)
select id, 1, 'seed', $cms${"fields":{"pme-et-startups.page.a-1":{"text":"Aller au contenu","href":"#main"},"pme-et-startups.header.card_index-1":{"href":"index.html"},"pme-et-startups.page.a-2":{"text":"Accueil","href":"index.html"},"pme-et-startups.page.a-3":{"text":"Cas d'usage","href":"cabinets.html"},"pme-et-startups.page.span-1":{"text":"PME & startups"},"pme-et-startups.s1.span-1":{"text":"Cas d'usage"},"pme-et-startups.s1.h1-1":{"text":"Un pilotage financier clair, sans équipe de contrôle de gestion."},"pme-et-startups.s1.p-1":{"text":"En PME et en startup, le pilotage financier est rarement le métier de celui qui s'en occupe. Ana reprend la production récurrente et transforme les données comptables en indicateurs de gestion à jour, pour que les décisions s'appuient sur des chiffres fiables, pas sur un ressenti."},"pme-et-startups.s2.span-1":{"text":"Constat"},"pme-et-startups.s2.span-2":{"text":"Le pilotage financier revient toujours au mauvais moment"},"pme-et-startups.s2.span-3":{"text":"Personne n'a le contrôle de gestion comme métier, donc les décisions se prennent à vue plutôt que sur des chiffres."},"pme-et-startups.s2.span-4":{"text":"Voir le détail"},"pme-et-startups.s2.li-1":{"text":"La marge par produit ou par client se calcule à la main, quand quelqu'un a le temps."},"pme-et-startups.s2.li-2":{"text":"Le suivi budgétaire se lit dans un tableur mis à jour de manière irrégulière."},"pme-et-startups.s2.li-3":{"text":"Les dérives de coûts ne sont repérées qu'à la clôture, trop tard pour agir."},"pme-et-startups.s2.li-4":{"text":"Les questions du board ou des investisseurs arrivent deux mois après les faits, quand plus personne ne se souvient."},"pme-et-startups.s2.span-5":{"text":"Périmètre"},"pme-et-startups.s2.span-6":{"text":"Ce qu'Ana reprend dès le premier mois"},"pme-et-startups.s2.span-7":{"text":"La production récurrente et le contrôle de gestion : collecte, rapprochement, suivi budgétaire, indicateurs de pilotage."},"pme-et-startups.s2.span-8":{"text":"Voir le détail"},"pme-et-startups.s2.li-5":{"text":"Collecte automatique des factures d'achat et des justificatifs, avec relance des manquants."},"pme-et-startups.s2.li-25":{"text":"Rapprochement bancaire refait à chaque import, écarts signalés aussitôt."},"pme-et-startups.s2.li-26":{"text":"Suivi budgétaire par ligne, avec l'écart au réalisé mis à jour à chaque import."},"pme-et-startups.s2.li-8":{"text":"Tableau de bord hebdomadaire : trésorerie, marge, principaux indicateurs de gestion."},"pme-et-startups.s2.span-9":{"text":"Cadre"},"pme-et-startups.s2.span-10":{"text":"Votre expert-comptable reste au centre de la comptabilité"},"pme-et-startups.s2.span-11":{"text":"Ana prend en charge le contrôle de gestion ; le cabinet garde la comptabilité et sa signature. Rien ne change dans la répartition des rôles."},"pme-et-startups.s2.span-12":{"text":"Voir le détail"},"pme-et-startups.s2.li-9":{"text":"Le cabinet garde l'accès à son logiciel et à ses journaux, sans changer d'outil."},"pme-et-startups.s2.li-10":{"text":"Les indicateurs de gestion d'Ana s'appuient sur les écritures validées par le cabinet."},"pme-et-startups.s2.li-11":{"text":"Le déclaratif reste du périmètre du cabinet ; Ana s'occupe du pilotage, pas de la comptabilité légale."},"pme-et-startups.s2.li-12":{"text":"Le journal complet est disponible pour la révision."},"pme-et-startups.s2.span-13":{"text":"Pilotage"},"pme-et-startups.s2.span-14":{"text":"Ce que vous voyez côté dirigeant"},"pme-et-startups.s2.span-15":{"text":"Les indicateurs de gestion qui comptent, disponibles sans les demander."},"pme-et-startups.s2.span-16":{"text":"Voir le détail"},"pme-et-startups.s2.li-13":{"text":"Trésorerie actuelle et projetée à 8 semaines."},"pme-et-startups.s2.li-27":{"text":"Marge par produit, par client ou par projet, mise à jour à chaque import."},"pme-et-startups.s2.li-15":{"text":"Écart au budget ligne par ligne, avec les dérives signalées tôt."},"pme-et-startups.s2.li-16":{"text":"Charges récurrentes et engagements à venir."},"pme-et-startups.s2.span-17":{"text":"Démarrage"},"pme-et-startups.s2.span-25":{"text":"Un pilote court, en trois étapes"},"pme-et-startups.s2.span-19":{"text":"Sur un périmètre restreint, avec un gain mesuré avant tout engagement."},"pme-et-startups.s2.span-20":{"text":"Voir le détail"},"pme-et-startups.s2.li-28":{"text":"Étape 1 : raccordement des flux et calibrage des règles en mode observation."},"pme-et-startups.s2.li-29":{"text":"Étape 2 : passage en validation humaine sur les tâches les plus répétitives."},"pme-et-startups.s2.li-30":{"text":"Étape 3 : mesure du temps repris et décision d'élargir ou d'arrêter."},"pme-et-startups.s2.li-20":{"text":"Aucune reprise d'historique n'est demandée pour démarrer."},"pme-et-startups.s2.span-21":{"text":"Cas limite"},"pme-et-startups.s2.span-22":{"text":"Levée de fonds ou due diligence"},"pme-et-startups.s2.span-23":{"text":"Des comptes tenus à jour et des indicateurs de gestion fiables changent la préparation."},"pme-et-startups.s2.span-24":{"text":"Voir le détail"},"pme-et-startups.s2.li-21":{"text":"Les pièces sont attachées aux écritures, pas éparpillées dans des boîtes mail."},"pme-et-startups.s2.li-22":{"text":"Chaque décision automatisée est explicable et horodatée."},"pme-et-startups.s2.li-23":{"text":"Les reportings récurrents existent déjà, il n'y a pas à les reconstituer."},"pme-et-startups.s2.li-24":{"text":"L'historique des relances documente la qualité du poste client."},"pme-et-startups.s3.span-1":{"text":"Ce qui change en PME"},"pme-et-startups.s3.p-1":{"text":"Sans équipe de contrôle de gestion, la question n'est pas d'avoir plus de chiffres, mais d'avoir les bons, à jour."},"pme-et-startups.s3.p-2":{"text":"Trois indicateurs fiables valent mieux qu'un tableau de bord complet que personne ne met à jour."},"pme-et-startups.s4.h2-1":{"text":"Voyons ce qu'Ana reprendrait chez vous."},"pme-et-startups.s4.p-2":{"text":"Une courte démo, sur vos propres flux : on cartographie les tâches automatisables et le gain attendu."},"pme-et-startups.s4.a-1":{"text":"Demander une démo","href":"demo.html"},"pme-et-startups.page.a-4":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4"],"hidden":[]},"seo":{"title":"Ana Finance pour PME et startups","description":"Automatisez votre comptabilité et votre reporting financier sans recruter une équipe finance complète.","ogTitle":"Ana Finance pour PME et startups","ogDescription":"Automatisez votre comptabilité et votre reporting financier sans recruter une équipe finance complète.","ogImage":null,"canonical":"","noindex":false}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
