insert into public.page_revisions (page_id, number, kind, content, message)
select id, 1, 'seed', $cms${"fields":{"ressources.page.a-1":{"text":"Aller au contenu","href":"#main"},"ressources.header.card_index-1":{"href":"index.html"},"ressources.s1.span-1":{"text":"Ressources"},"ressources.s1.h1-1":{"text":"Tarifs, conformité et réponses aux questions qui décident."},"ressources.s1.p-1":{"text":"Ce que coûte Ana, comment vos données sont traitées, et tout ce qu'on nous demande avant de signer."},"ressources.s2.span-1":{"text":"Tarifs"},"ressources.s2.h2-1":{"text":"Le prix suit vos volumes, pas une grille standard."},"ressources.s2.p-1":{"text":"Deux cabinets de même taille n'automatisent pas les mêmes tâches : nous chiffrons après avoir vu vos dossiers et vos outils. Voici comment le devis se construit."},"ressources.s2.div-1":{"text":"1"},"ressources.s2.h3-1":{"text":"Ce qui détermine le prix"},"ressources.s2.p-2":{"text":"Le nombre de dossiers ou d'entités traités, les agents activés (comptable, clôture) et les connecteurs à mettre en place."},"ressources.s2.div-2":{"text":"2"},"ressources.s2.h3-2":{"text":"Ce qui est toujours inclus"},"ressources.s2.p-7":{"text":"Le cockpit financier, le journal complet, les mises à jour des agents et l'accompagnement de votre équipe pendant le déploiement."},"ressources.s2.div-3":{"text":"3"},"ressources.s2.h3-3":{"text":"Comment on démarre"},"ressources.s2.p-4":{"text":"Un pilote au forfait sur un périmètre restreint, facturé une seule fois. S'il tient ses promesses, il bascule en abonnement annuel ; sinon, il s'arrête là."},"ressources.s2.h3-5":{"text":"Une offre construite avec vous"},"ressources.s2.p-8":{"text":"Chaque structure a ses volumes, ses outils et ses priorités. Selon vos cas d'usage, nous travaillons le montant avec vous pour vous faire l'offre la plus adaptée à votre situation : périmètre du pilote, agents activés, volumes traités et rythme de déploiement."},"ressources.s2.a-2":{"text":"Obtenir mon devis","href":"demo.html"},"ressources.s2.p-6":{"text":"Devis remis sous 48 h après la démonstration, sans engagement. Aucun frais d'installation caché : les connecteurs développés pendant le pilote sont inclus dans son forfait."},"ressources.s3.span-1":{"text":"Confiance & conformité"},"ressources.s3.h2-1":{"text":"Des agents autonomes, jamais incontrôlés."},"ressources.s3.h3-1":{"text":"Hébergement UE"},"ressources.s3.p-1":{"text":"Données stockées et traitées dans l'Union européenne, chiffrées en transit et au repos."},"ressources.s3.h3-2":{"text":"Validation humaine"},"ressources.s3.p-2":{"text":"Aucune écriture définitive sans revue : l'agent propose, vous validez, la responsabilité reste humaine."},"ressources.s3.h3-3":{"text":"Traçabilité totale"},"ressources.s3.p-3":{"text":"Chaque décision est journalisée, explicable et réversible, journal complet exportable."},"ressources.s3.h3-4":{"text":"RGPD & AI Act"},"ressources.s3.p-4":{"text":"Accord de sous-traitance (art. 28), registre des traitements, transparence sur l'usage de l'IA."},"ressources.s4.span-1":{"text":"FAQ"},"ressources.s4.h2-1":{"text":"Les questions qu'on nous pose avant de signer."},"ressources.s4.summary-1":{"text":"Ana remplace-t-elle mon expert-comptable ?"},"ressources.s4.p-1":{"text":"Non. Ana est un outil d'automatisation destiné aux professionnels : elle prépare et exécute des tâches de production, mais la revue, la validation et la responsabilité restent celles de l'expert-comptable ou de la direction financière. Ana ne fournit ni conseil comptable, ni fiscal, ni juridique."},"ressources.s4.summary-2":{"text":"Où sont hébergées mes données ?"},"ressources.s4.p-2":{"text":"Dans l'Union européenne, chiffrées en transit et au repos. Ana agit comme sous-traitant au sens du RGPD : accord de sous-traitance (art. 28), liste des sous-traitants ultérieurs et durées de conservation communiqués sur demande."},"ressources.s4.summary-3":{"text":"Ana accède-t-elle à mes comptes bancaires ?"},"ressources.s4.p-3":{"text":"En lecture seule, via un prestataire agréé DSP2, et uniquement après votre consentement explicite. Aucune initiation de paiement n'est réalisée sans validation humaine."},"ressources.s4.summary-4":{"text":"Comment les décisions de l'IA sont-elles contrôlées ?"},"ressources.s4.p-7":{"text":"Chaque action d'agent est journalisée, explicable et réversible, avec un journal complet exportable. Le niveau d'autonomie est paramétrable par type de tâche, et la supervision humaine reste obligatoire sur les écritures définitives."},"ressources.s4.summary-5":{"text":"Combien de temps pour démarrer ?"},"ressources.s4.p-5":{"text":"Le pilote démarre sur un périmètre restreint en quelques semaines, sans migration de votre système comptable. Les connecteurs manquants sont développés pendant cette phase."},"ressources.s4.summary-6":{"text":"Combien ça coûte ?"},"ressources.s4.p-8":{"text":"Sur devis. Selon vos cas d'usage, le nombre de dossiers et les agents activés, nous construisons avec vous l'offre la plus adaptée ; elle vous est remise après la démonstration."},"ressources.s5.span-1":{"text":"Contact"},"ressources.s5.h2-2":{"text":"Une question ? Écrivez-nous."},"ressources.s5.p-4":{"html":"Produit, sécurité, tarifs : posez votre question, un membre de l'équipe vous répond sous un jour ouvré. Vous pouvez aussi nous écrire à <a href=\"mailto:contact@ana-finance.com\" style=\"text-decoration:underline;\">contact@ana-finance.com</a>. Pour voir Ana travailler sur vos dossiers, <a href=\"demo.html\" style=\"text-decoration:underline;\">demandez plutôt une démo</a>."},"ressources.s5.p-5":{"text":"Message envoyé."},"ressources.s5.p-6":{"text":"Un membre de l'équipe Ana vous répond sous un jour ouvré."},"ressources.s5.button-2":{"text":"Envoyer un autre message"},"ressources.s5.p-7":{"text":"* Champs obligatoires"},"ressources.s5.span-3":{"text":"*"},"ressources.s5.span-4":{"text":"Ce champ est obligatoire."},"ressources.s5.span-5":{"text":"*"},"ressources.s5.span-6":{"html":"Structure <span style=\"font-weight:400;color:#6b6880;\">(optionnel)</span>"},"ressources.s5.span-7":{"html":"Téléphone <span style=\"font-weight:400;color:#6b6880;\">(optionnel)</span>"},"ressources.s5.span-8":{"text":"*"},"ressources.s5.span-9":{"text":"Ce champ est obligatoire."},"ressources.s5.a-1":{"text":"politique de confidentialité","href":"mentions-legales.html#confidentialite"},"ressources.s5.span-10":{"text":"*"},"ressources.s6.h3-1":{"text":"Passez à la vitesse agentic."},"ressources.s6.a-1":{"text":"Demander une démo","href":"demo.html"},"ressources.page.a-2":{"text":"Demander une démo","href":"demo.html"}},"sections":{"order":["s1","s2","s3","s4","s5","s6"],"hidden":[]},"seo":{"title":"Tarifs, sécurité et questions fréquentes — Ana Finance","description":"Tarifs sur devis, sécurité et conformité, réponses aux questions fréquentes et contact : l'essentiel avant de démarrer avec Ana Finance.","ogTitle":"Tarifs, sécurité et questions fréquentes — Ana Finance","ogDescription":"Tarifs sur devis, sécurité et conformité, réponses aux questions fréquentes et contact : l'essentiel avant de démarrer avec Ana Finance.","ogImage":null,"canonical":"","noindex":false,"rev":1}}$cms$::jsonb, 'Contenu d''origine du site' from public.pages
